// GENERATED_LOCALES_END

/** Collapse a stack/manifest code to its base translation locale. */
function baseLocale(lang: string): string {
  return (lang || "en").split("-")[0].toLowerCase()
}

/** Translate `key` into `lang` (native language), interpolating {name} params.
 *  Falls back to English per-key so nothing is ever blank. */
export function t(key: I18nKey, lang: string, params?: Record<string, string>): string {
  const loc = baseLocale(lang)
  // Exact locale first (zh-Hans vs zh-Hant, ko-polite, pa-Arab/pa-Guru, pt-BR/pt-PT
  // all differ), then the collapsed base (es-MX → es), then English, then the key.
  const s =
    (LOCALES[lang] as Partial<Dict> | undefined)?.[key] ??
    (LOCALES[loc] as Partial<Dict> | undefined)?.[key] ??
    en[key] ??
    key
  if (!params) return s
  return Object.entries(params).reduce((acc, [k, v]) => acc.split(`{${k}}`).join(v), s)
}

/** Bind `t` to one native locale. */
export function bindT(lang: string): (key: I18nKey, params?: Record<string, string>) => string {
  return (key, params) => t(key, lang, params)
}

// ---- the ambient native locale (set ONCE at mount; see App.buildRig) --------
// A pack instance renders in one native language for its whole lifetime, so the
// active locale is module-level state rather than threaded through every prop.
// Components + actions call `ct("key")`; tests that never call setUiLang render
// in clean English (default "en").
let _uiLang = "en"

/** Set the native UI language for this pack instance (languages[0]). */
export function setUiLang(lang: string): void {
  _uiLang = lang || "en"
}

/** The current native language. */
export function uiLang(): string {
  return _uiLang
}

// ---- writing direction ------------------------------------------------------
// The native UI language decides the pack's reading direction (matches the host
// app's RTL_LANGUAGES list). Most layout flips for free off an ancestor
// `dir="rtl"`; this lets the pack stamp its own root + lets standalone dev force
// RTL via `?lang=ar`. Components that need JS-side mirroring (the ribbon) read
// `uiDir()`; CSS keys off `[dir="rtl"]`.
const RTL_LANGS = new Set(["ar", "he", "fa", "pa-Arab", "ur"])

/** Is `lang` written right-to-left? Tolerant of regional variants (`ar-EG`) and
 *  scripted regional variants (`pa-Arab-PK`) — a 4-letter script subtag decides
 *  direction independently of region, so it's checked before the bare base
 *  (which keeps Gurmukhi `pa-Guru` LTR while Shahmukhi `pa-Arab` is RTL). */
export function isRtlLang(lang: string): boolean {
  if (!lang) return false
  if (RTL_LANGS.has(lang)) return true
  const parts = lang.split("-")
  const base = parts[0].toLowerCase()
  const script = parts.find((p) => /^[a-zA-Z]{4}$/.test(p))
  if (script) {
    const norm = `${base}-${script[0].toUpperCase()}${script.slice(1).toLowerCase()}`
    if (RTL_LANGS.has(norm)) return true
  }
  return RTL_LANGS.has(base)
}

/** The current native language's writing direction ("rtl" | "ltr"). */
export function uiDir(): "rtl" | "ltr" {
  return isRtlLang(_uiLang) ? "rtl" : "ltr"
}

/** Translate `key` into the ambient native language. The seam components/actions
 *  use: `ct("score.noTrack")`. Music loan-words are NOT keyed — pass as-is. */
export function ct(key: I18nKey, params?: Record<string, string>): string {
  return t(key, _uiLang, params)
}

// ---- dev / test exports ----
export const SOURCE_EN: Dict = en
export const ALL_KEYS = Object.keys(en) as I18nKey[]
export function presentLocales(): string[] {
  return Object.keys(LOCALES)
}
export const __LOCALES_FOR_TEST = LOCALES
